   // memset length as (subsampled_width - old_width), which would underflow to a
   // huge value on a shrink request and write past the end of the pixel plane.
-  // Reject it up front (GHSA-hqc2-cx5m-g6ff).
-  if (width < m_width || height < m_height) {
-    return Error{heif_error_Usage_error,
-                 heif_suberror_Invalid_parameter_value,
-                 "Cannot extend an image to a size smaller than its current size."};
-  }

   // Nothing to do when the target already matches the current size.
   if (width == m_width && height == m_height) {
     return Error::Ok;
   }

+  // A Cb/Cr plane is the only plane whose size can differ from the logical image
+  // size without the non-uniform check in the loop below rejecting it, so it is
+  // also the only plane that can be larger than the extent the target maps to
+  // while the target itself is not smaller than the image. Validate the chroma
+  // planes up front so a rejected request cannot leave the image partially
+  // modified (GHSA-hqc2-cx5m-g6ff). Planes that follow the logical image size
+  // shrink only together with the image itself.
+  for (const auto& component : m_storage) {
+    if (component.m_channel != heif_channel_Cb &&
+        component.m_channel != heif_channel_Cr) {
+      continue;
+    }
+
+    uint32_t subsampled_width, subsampled_height;
+    get_subsampled_size(width, height, component.m_channel, m_chroma,
+                        &subsampled_width, &subsampled_height);
+
+    if (subsampled_width < component.m_width || subsampled_height < component.m_height) {
+      return Error{heif_error_Usage_error,
+                   heif_suberror_Invalid_parameter_value,
+                   "Cannot extend an image to a size smaller than an existing chroma plane."};
+    }
+  }
+
   for (auto& component : m_storage) {
     // See extend_padding_to_size(): get_subsampled_size() assumes a non-Cb/Cr
     // component has the full logical image size, so we cannot compute a correct
diff --git a/tests/extend_to_size_checks.cc b/tests/extend_to_size_checks.cc
index 44090dcc..fb77da15 100644
--- a/tests/extend_to_size_checks.cc
+++ b/tests/extend_to_size_checks.cc
@@ -30,20 +30,26 @@
 // Regression tests for HeifPixelImage::extend_to_size_with_zero().
 //
 // This function only grows an image. The per-row right-edge fill computes its
-// memset length as (subsampled_width - old_width); on a shrink request that
-// unsigned subtraction underflows to a huge value and the memset writes far
-// past the end of the pixel plane (GHSA-hqc2-cx5m-g6ff, reachable through the
-// public heif_image_extend_to_size_fill_with_zero() API). The function now
-// rejects any target smaller than the current size before touching a plane.
+// memset length as (subsampled_width - old_width); when the target maps to a
+// per-component size smaller than the plane, that unsigned subtraction
+// underflows to a huge value and the memset writes far past the end of the
+// pixel plane (GHSA-hqc2-cx5m-g6ff, reachable through the public
+// heif_image_extend_to_size_fill_with_zero() API). The chroma planes are
+// validated against the target before any fill runs, so the tests below shrink
+// a 4:2:0 image, where the subsampled chroma extent is the first to fall below
+// its plane size.

 TEST_CASE("extend_to_size_with_zero rejects a smaller width") {
   auto* limits = heif_get_global_security_limits();

   auto image = std::make_shared<HeifPixelImage>();
-  image->create(64, 8, heif_colorspace_monochrome, heif_chroma_monochrome);
+  image->create(64, 8, heif_colorspace_YCbCr, heif_chroma_420);
   REQUIRE(image->add_channel(heif_channel_Y, 64, 8, 8, limits).error_code == heif_error_Ok);
+  REQUIRE(image->add_channel(heif_channel_Cb, 32, 4, 8, limits).error_code == heif_error_Ok);
+  REQUIRE(image->add_channel(heif_channel_Cr, 32, 4, 8, limits).error_code == heif_error_Ok);

-  // Requesting width 1 < 64 previously underflowed the fill length -> heap OOB write.
+  // Width 1 maps to a chroma extent of 1 < 32, which previously underflowed
+  // the fill length -> heap OOB write.
   Error err = image->extend_to_size_with_zero(1, 8, limits);
   REQUIRE(err.error_code == heif_error_Usage_error);
   REQUIRE(err.sub_error_code == heif_suberror_Invalid_parameter_value);
@@ -57,8 +63,10 @@ TEST_CASE("extend_to_size_with_zero rejects a smaller height") {
   auto* limits = heif_get_global_security_limits();

   auto image = std::make_shared<HeifPixelImage>();
-  image->create(8, 64, heif_colorspace_monochrome, heif_chroma_monochrome);
+  image->create(8, 64, heif_colorspace_YCbCr, heif_chroma_420);
   REQUIRE(image->add_channel(heif_channel_Y, 8, 64, 8, limits).error_code == heif_error_Ok);
+  REQUIRE(image->add_channel(heif_channel_Cb, 4, 32, 8, limits).error_code == heif_error_Ok);
+  REQUIRE(image->add_channel(heif_channel_Cr, 4, 32, 8, limits).error_code == heif_error_Ok);

   Error err = image->extend_to_size_with_zero(8, 1, limits);
   REQUIRE(err.error_code == heif_error_Usage_error);

